#!/usr/bin/env node
/**
 * Writes the square site logo / favicons into public/ before the Vite build.
 *
 * Google only shows a logo next to a search result when it can fetch a *square*
 * image; the original artwork is 745x576, so it is pre-padded onto a square
 * canvas here. The PNG bytes are embedded below because the repository is
 * updated through a text-only API that cannot commit binary files.
 */
import { mkdirSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const publicDir = join(root, 'public');
mkdirSync(publicDir, { recursive: true });

